const SC={Motion:'#F2B43C',Matter:'#8C6CF0',Time:'#3CC6D8',Energy:'#F07A3C',Life:'#5CC46A',Spirit:'#E05CB4'};
const LF2=n=>String(Math.round(n*100)/100);
const LPATH=(()=>{const P=(n,ro,ri,o)=>{let d='';for(let i=0;i<n*2;i++){const a=(i/(n*2))*Math.PI*2-Math.PI/2+(o||0),rr=i%2?ri:ro;d+=(i?'L':'M')+LF2(12+Math.cos(a)*rr)+' '+LF2(12+Math.sin(a)*rr);}return d+'z';};
 const Sc=(n,r0,r1)=>{let d='';for(let i=0;i<=n;i++){const a=(i/n)*Math.PI*2-Math.PI/2,x=12+Math.cos(a)*r0,y=12+Math.sin(a)*r0;if(!i){d='M'+LF2(x)+' '+LF2(y);continue;}const m=((i-.5)/n)*Math.PI*2-Math.PI/2;d+='Q'+LF2(12+Math.cos(m)*r1)+' '+LF2(12+Math.sin(m)*r1)+' '+LF2(x)+' '+LF2(y);}return d+'z';};
 const tk=[];for(let i=0;i<12;i++){const a=i/12*Math.PI*2,r0=i%3?9.1:8.5;tk.push('M'+LF2(12+Math.cos(a)*r0)+' '+LF2(12+Math.sin(a)*r0)+'L'+LF2(12+Math.cos(a)*9.9)+' '+LF2(12+Math.sin(a)*9.9));}
 return {burst:P(10,11.3,10),scal:Sc(10,9.9,12.2),tear:'M12 .6C15.4 4.6 21.2 8 21.2 14a9.2 9.2 0 0 1-18.4 0C2.8 8 8.6 4.6 12 .6z',ticks:tk.join('')};})();
